mapper.select:
SELECT WITHDRAWN_AT
FROM WITHDRAWN_USERS
WHERE (
    EMAIL    = #{email}
     OR 
    LOGIN_ID = #{loginId}
)
AND WITHDRAWN_AT > SYSDATE - 30
ORDER BY WITHDRAWN_AT DESC
FETCH FIRST 1 ROWS ONLY

SELECT LOGIN_ID FROM USERS
WHERE NAME = #{name}
  AND EMAIL = #{email}
  AND IS_DELETED = 'N'
  AND OAUTH_PROVIDER IS NULL
FETCH FIRST 1 ROWS ONLY

SELECT * FROM USERS
WHERE LOGIN_ID = #{loginId}
  AND EMAIL = #{email}
  AND IS_DELETED = 'N'
  AND OAUTH_PROVIDER IS NULL
